using System;using System.Data;using System.Text;public partial class MyBets:System.Web.UI.Page{public string betsHtml="";protected void Page_Load(object sender,EventArgs e){if(Session["user"]==null){Response.Redirect("Login.aspx");return;}DataTable dt=MyAdoHelper.ExecuteDataTable("SELECT Bets.*,C.ClubName,A.ClubName ClubA,B.ClubName ClubB FROM Bets INNER JOIN Games ON Bets.GameId=Games.GameId INNER JOIN Clubs C ON Bets.BetClubId=C.ClubId INNER JOIN Clubs A ON Games.ClubAId=A.ClubId INNER JOIN Clubs B ON Games.ClubBId=B.ClubId WHERE Bets.UserId="+Session["userId"]+" ORDER BY BetDate DESC");StringBuilder s=new StringBuilder("<table class='dataTable'><tr><th>משחק</th><th>קבוצה</th><th>מטבעות</th><th>תאריך</th><th>מצב</th></tr>");for(int i=0;i<dt.Rows.Count;i++){int r=Convert.ToInt32(dt.Rows[i]["BetResult"]);string status=r==-1?"ממתין":r==1?"נכון":"לא נכון";s.Append("<tr><td>"+dt.Rows[i]["ClubA"]+" נגד "+dt.Rows[i]["ClubB"]+"</td><td>"+dt.Rows[i]["ClubName"]+"</td><td>"+dt.Rows[i]["BetCoins"]+"</td><td>"+Convert.ToDateTime(dt.Rows[i]["BetDate"]).ToString("dd/MM/yyyy HH:mm")+"</td><td>"+status+"</td></tr>");}s.Append("</table>");betsHtml=s.ToString();}}